# %% Cell 1
import json
import os
import tensorflow as tf
import pandas as pd
from pathlib import Path
import shutil
import matplotlib.pyplot as plt
from tensorflow.keras import layers, Model
from tensorflow.keras.applications import EfficientNetV2B0 
import os
import time
from tensorflow.keras.callbacks import (
    EarlyStopping,
    ModelCheckpoint,
    ReduceLROnPlateau,
    CSVLogger
)
import numpy as np
import sklearn
from sklearn.metrics import (
    classification_report,
    confusion_matrix,
    ConfusionMatrixDisplay,
    accuracy_score,
    f1_score,
    balanced_accuracy_score
)

#Configuramos directorio de resultados y metadatos, y modelos
RESULTS_DIR = "./resultados"
MODELOS_DIR = "./"
os.makedirs(RESULTS_DIR, exist_ok=True)
os.makedirs(MODELOS_DIR, exist_ok=True)

BATCH_SIZE = 16  # A 32 nos quedamos si memoria
X_SIZE = 224
Y_SIZE = 224
IMG_SIZE = (X_SIZE, Y_SIZE) # A 224 nos quedamos sin recursos
SEED = 42
EPOCHS = 10


ruta_dataset = "../../data/processed/"
# Nuevas rutas locales
ruta_train = ruta_dataset + "/train"
ruta_val = ruta_dataset + "/val"
ruta_test = ruta_dataset + "/test"

# Cargar TRAIN (Se queda listo para el entrenamiento)
train_ds = tf.keras.utils.image_dataset_from_directory(
    ruta_train,
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    label_mode='int',
    shuffle=True,
    seed=SEED
)

#Usamos class_names en validación y test para segurar que se usan los mismos índices
class_names = train_ds.class_names
NUM_CLASSES = len(class_names)

# Cargar VAL (Solo se llamará al final de cada época)
val_ds = tf.keras.utils.image_dataset_from_directory(
    ruta_val,
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    label_mode="int",
    class_names=class_names,
    shuffle=False
)

# Cargar TEST (Solo ocupará memoria al final de todo el entrenamiento)
test_ds = tf.keras.utils.image_dataset_from_directory(
    ruta_test,
    image_size=IMG_SIZE,
    batch_size=BATCH_SIZE,
    label_mode="int",
    class_names=class_names,
    shuffle=False
)

# Optimización de flujo (SIN .cache(), solo prefetch)
AUTOTUNE = tf.data.AUTOTUNE
train_ds = train_ds.prefetch(AUTOTUNE)
val_ds = val_ds.prefetch(AUTOTUNE)
test_ds = test_ds.prefetch(AUTOTUNE)

print("¡Datasets configurados para lectura bajo demanda desde el disco duro!")


# Guardamos metadatos.
metadata = {
    "class_names": list(class_names),
    "image_size": list(IMG_SIZE),
    "batch_size": BATCH_SIZE,
    "label_mode": "int",
    "seed": SEED,
    "tensorflow_version": tf.__version__,
    "EPOCHS": EPOCHS,
    "SEED": SEED,
    "MODELOS_DIR": MODELOS_DIR,
    "RESULTS_DIR": RESULTS_DIR,
    "DATASET_DIR": ruta_dataset
}

METADATA_PATH = Path(MODELOS_DIR) / "metadata.json"
METADATA_PATH.parent.mkdir(parents=True, exist_ok=True)

# Escribir el JSON.
METADATA_PATH.write_text(
    json.dumps(metadata, indent=2, ensure_ascii=False),
    encoding="utf-8",
)

print("Configuración guardada:", METADATA_PATH.resolve())

base_model = EfficientNetV2B0 (
    include_top=False,
    weights="imagenet",
    input_shape=(IMG_SIZE[0], IMG_SIZE[1], 3)
)

#Congelamos la red preentrenada
base_model.trainable = False

inputs = layers.Input(shape=(IMG_SIZE[0], IMG_SIZE[1], 3))

# Extracción de características
x = base_model(inputs, training=False)

# Clasificador
x = layers.GlobalAveragePooling2D()(x)
x = layers.Dropout(0.3)(x)

outputs = layers.Dense(
    NUM_CLASSES,
    activation="softmax"
)(x)


model = Model(inputs, outputs, name="baseline_efficientnetv2b0")

model.compile(
    optimizer=tf.keras.optimizers.Adam(learning_rate=0.001),
    loss="sparse_categorical_crossentropy",
    metrics=["accuracy"]
)

# Entrenamiento del modelo

callbacks = [
    ModelCheckpoint(
        f"{MODELOS_DIR}/baseline_efficientnetv2b0.keras",
        monitor="val_loss",
        save_best_only=True,
        verbose=1
    ),

    EarlyStopping(
        monitor="val_loss",
        patience=4,
        restore_best_weights=True,
        verbose=1
    ),

    ReduceLROnPlateau(
        monitor="val_loss",
        factor=0.2,
        patience=2,
        min_lr=1e-7,
        verbose=1
    ),

    CSVLogger(
        f"{RESULTS_DIR}/baseline_history.csv"
    )
]

inicio = time.time()

history = model.fit(
    train_ds,
    validation_data=val_ds,
    epochs=EPOCHS,
    callbacks=callbacks
)

duracion = time.time() - inicio

print(f"Tiempo de entrenamiento: {duracion / 60:.2f} minutos")

# Guardamos el modelo entrenado
# Nombre del modelo 
MODEL_PATH = Path(MODELOS_DIR) / "baseline_efficientnetv2b0.keras"

# Guardar el modelo completo
model.save(MODEL_PATH)

print(f"Modelo guardado en: {MODEL_PATH}")
print(f"Tamaño: {MODEL_PATH.stat().st_size / (1024**2):.2f} MB")

# Representamos la evolución de la precisión y de la pérdida durante el entrenamiento:
# - Si entrenamiento y validación mejoran juntos, el modelo está aprendiendo.
# - Si mejora el entrenamiento y empeora la validación hay *overfitting*.
# - Si los dos bajan puede haber *underfitting*.
# - Si la validación mejora más lento, hay que revisar la calidad y el equilibrio de los datos.

# %% Cell 8
def plot_history(history):
    hist = history.history

    fig, axes = plt.subplots(1, 2, figsize=(14, 5))

    axes[0].plot(hist["accuracy"], label="Train")
    axes[0].plot(hist["val_accuracy"], label="Validation")
    axes[0].set_title("Accuracy")
    axes[0].set_xlabel("Época")
    axes[0].legend()

    axes[1].plot(hist["loss"], label="Train")
    axes[1].plot(hist["val_loss"], label="Validation")
    axes[1].set_title("Loss")
    axes[1].set_xlabel("Época")
    axes[1].legend()

    plt.show()

plot_history(history)


# **Evaluación del modelo**
#
# Una precisión global elevada puede ocultar que el modelo clasifica mal algunas enfermedades menos representadas. Para visualizarlo usaremos:
# - *Accuracy*: porcentaje global de aciertos.
# - *Precision*: proporción de predicciones positivas correctas.
# - *Recall*: proporción de imágenes de una clase que consigue detectar.
# - *F1-score*: equilibrio entre precision y recall.
# - *Macro F1*: media del F1 de todas las clases, dando el mismo peso a cada enfermedad.


# Cargar el mejor modelo guardado
best_model = tf.keras.models.load_model(
    f"{MODELOS_DIR}/baseline_efficientnetv2b0.keras"
)

# Predicciones sobre validación
y_true = np.concatenate([
    labels.numpy() for images, labels in val_ds
])

y_prob = best_model.predict(val_ds)
y_pred = np.argmax(y_prob, axis=1)

print(classification_report(
    y_true,
    y_pred,
    target_names=class_names,
    digits=4,
    zero_division=0
))

print("Accuracy:", accuracy_score(y_true, y_pred))
print("Macro F1:", f1_score(y_true, y_pred, average="macro"))
print("Balanced accuracy:", balanced_accuracy_score(y_true, y_pred))

# %% Cell 10
#Matriz de confusión
cm = confusion_matrix(y_true, y_pred)

fig, ax = plt.subplots(figsize=(12, 12))

disp = ConfusionMatrixDisplay(
    confusion_matrix=cm,
    display_labels=class_names
)

disp.plot(
    ax=ax,
    xticks_rotation=90,
    cmap="Blues",
    colorbar=False
)

plt.title("Baseline EfficientNetB0 - Validación")
plt.tight_layout()
plt.show()


# Creamos un registro común para guardar los resultados y comparar los experimentos. Este registro crecerá a medida que incorporemos otros modelos

resultado_baseline = {
    "modelo": "EfficientNetB0",
    "tipo": "Transfer learning - capas congeladas",
    "resolucion": "224x224",
    "batch_size": BATCH_SIZE,
    "learning_rate": 0.001,
    "epochs": len(history.history["loss"]),
    "tiempo_minutos": round(duracion / 60, 2),
    "accuracy": float(accuracy_score(y_true, y_pred)),
    "macro_f1": float(f1_score(y_true, y_pred, average="macro")),
    "balanced_accuracy": float(
        balanced_accuracy_score(y_true, y_pred)
    )
}

resultados = pd.DataFrame([resultado_baseline])

resultados.to_csv(
    f"{RESULTS_DIR}/comparativa_modelos.csv",
    index=False
)
